import type Phaser from 'phaser';
import { TEX } from '../art/manifest';
import { UI_SLICE } from '../art/placeholders/textures';

/** Beveled 9-slice panel generated by code (ui.panel). Origin at the top-left. */
export function addPanel(
	scene: Phaser.Scene,
	x: number,
	y: number,
	width: number,
	height: number,
	texture: string = TEX.uiPanel,
): Phaser.GameObjects.NineSlice {
	const s = UI_SLICE;
	return scene.add.nineslice(x, y, texture, undefined, width, height, s, s, s, s).setOrigin(0, 0);
}
